(7632958, 1237810, 114285, '<td valign="top">Simple beauty</td>', 'Simple beauty', '2019-06-19 02:23:48.000000', NULL, 1),
(7632964, 1237825, 114285, '<td valign="top">Nice crop and macro, but image is slightly noisey, unless that''s how you like it :)</td>', 'Nice crop and macro, but image is slightly noisey, unless that''s how you like it :)', '2019-06-19 05:19:42.000000', NULL, 1),
(7632965, 1237851, 114285, '<td valign="top">Great sharpness in the foreground, but tends to be slightly OOF to the right of this critter.</td>', 'Great sharpness in the foreground, but tends to be slightly OOF to the right of this critter.', '2019-06-19 05:20:37.000000', NULL, 1),
(7632966, 1237747, 114285, '<td valign="top">This is the 2nd image almost in a row that is quite noisey, either you like it that way or you haven''t tried to reduce it via PS. Looks like an interesting bug you have there.</td>', 'This is the 2nd image almost in a row that is quite noisey, either you like it that way or you haven''t tried to reduce it via PS. Looks like an interesting bug you have there.', '2019-06-19 05:21:55.000000', NULL, 1),
(7632967, 1237821, 114285, '<td valign="top">Love the light smack bang in the middle, great macro!</td>', 'Love the light smack bang in the middle, great macro!', '2019-06-19 05:22:40.000000', NULL, 1),
(7632968, 1237770, 114285, '<td valign="top">Too fuzzy to really see what''s going on, but looks quite interesting.</td>', 'Too fuzzy to really see what''s going on, but looks quite interesting.', '2019-06-19 05:23:13.000000', NULL, 1),
(7632969, 1237736, 114285, '<td valign="top">Excellent shot, one of the better ones so far, all the best!</td>', 'Excellent shot, one of the better ones so far, all the best!', '2019-06-19 05:25:13.000000', NULL, 1),
(7632970, 1237852, 114285, '<td valign="top">Brilliant sharpness! This is quite amazing, I especially love the brightly colored wings, should do well indeed!</td>', 'Brilliant sharpness! This is quite amazing, I especially love the brightly colored wings, should do well indeed!', '2019-06-19 05:27:16.000000', NULL, 1),
(7632971, 1237792, 114285, '<td valign="top">Amazing shot, well done!</td>', 'Amazing shot, well done!', '2019-06-19 05:28:22.000000', NULL, 1),
(7632972, 1237871, 114285, '<td valign="top">Shame the right one is OOF, the left bug is not exactly sharp either. I would of rotated this also, but hey the sure are very interesting bugs!</td>', 'Shame the right one is OOF, the left bug is not exactly sharp either. I would of rotated this also, but hey the sure are very interesting bugs!', '2019-06-19 05:29:39.000000', NULL, 1),
(7632973, 1237863, 114285, '<td valign="top">This is amazingly sharp! I feel it most likely will ribbon. It pops and the structure is spot on! All the best.</td>', 'This is amazingly sharp! I feel it most likely will ribbon. It pops and the structure is spot on! All the best.', '2019-06-19 05:30:46.000000', NULL, 1),
(7632980, 1237838, 65234, '<td valign="top">Unbelievable timing on the capture! Just an incredible image.</td>', 'Unbelievable timing on the capture! Just an incredible image.', '2019-06-19 09:10:00.000000', NULL, 1),
(7632981, 1237756, 65234, '<td valign="top">Love the DOF on these many bees. The 2 primary bees look like they''re having a conversation ... and they may well be &lt;pun sort of intended&gt;.</td>', 'Love the DOF on these many bees. The 2 primary bees look like they''re having a conversation ... and they may well be <pun sort of intended>.', '2019-06-19 09:11:35.000000', NULL, 1),
(7632982, 1237808, 65234, '<td valign="top">Perfect DOF and detail on this guy. And I know crab spiders are pretty small, so kudos.</td>', 'Perfect DOF and detail on this guy. And I know crab spiders are pretty small, so kudos.', '2019-06-19 09:12:16.000000', NULL, 1),
(7632983, 1237863, 65234, '<td valign="top">Sharp as can be, which seems perfectly appropriate for a grasshopper. Nice DOF and detail.</td>', 'Sharp as can be, which seems perfectly appropriate for a grasshopper. Nice DOF and detail.', '2019-06-19 09:13:09.000000', NULL, 1),
(7632984, 1237520, 65234, '<td valign="top">Gorgeous detail. Funny how pretty pesky flies can look up close.</td>', 'Gorgeous detail. Funny how pretty pesky flies can look up close.', '2019-06-19 09:13:38.000000', NULL, 1),
(7632985, 1237657, 65234, '<td valign="top">Nice detail on the wings; a little dark on the head on my screen.</td>', 'Nice detail on the wings; a little dark on the head on my screen.', '2019-06-19 09:14:09.000000', NULL, 1),
(7632987, 1237851, 65234, '<td valign="top">And did you let your model live, or were those someone else''s tomatoes LOL? Very nice detail on this guy.</td>', 'And did you let your model live, or were those someone else''s tomatoes LOL? Very nice detail on this guy.', '2019-06-19 09:14:54.000000', NULL, 1),
