(7632992, 1237788, 65234, '<td valign="top">Monarch! I haven''t seen any here yet. Nice DOF. A wee bit dark on the head on my monitor.</td>', 'Monarch! I haven''t seen any here yet. Nice DOF. A wee bit dark on the head on my monitor.', '2019-06-19 09:17:56.000000', NULL, 1),
(7632993, 1237684, 65234, '<td valign="top">Aww, poor guy has shredded wings. Nice DOF and detail.</td>', 'Aww, poor guy has shredded wings. Nice DOF and detail.', '2019-06-19 09:18:30.000000', NULL, 1),
(7632994, 1237810, 65234, '<td valign="top">Love the composition and that nicely complementary background. The near eye looks just slightly soft to my eye, but the mouth and legs are nice and sharp.</td>', 'Love the composition and that nicely complementary background. The near eye looks just slightly soft to my eye, but the mouth and legs are nice and sharp.', '2019-06-19 09:20:13.000000', NULL, 1),
(7632995, 1237747, 65234, '<td valign="top">Don''t think we''ll see many of those this year around here. Nice detail on the wing. Did you want all the noise? Some people like that grain. Personally, I''d have reduced the noise for a nice, smooth background.</td>', 'Don''t think we''ll see many of those this year around here. Nice detail on the wing. Did you want all the noise? Some people like that grain. Personally, I''d have reduced the noise for a nice, smooth background.', '2019-06-19 09:22:22.000000', NULL, 1),
(7632996, 1237840, 65234, '<td valign="top">A lot to see here, which is great, but I really wish that dragon''s eye was in focus. Maybe a smidge more DOF?</td>', 'A lot to see here, which is great, but I really wish that dragon''s eye was in focus. Maybe a smidge more DOF?', '2019-06-19 09:24:08.000000', NULL, 1),
