(7633064, 1237824, 149964, '<td valign="top">Beautiful colours. Would have liked the bug to have been a little less soft.</td>', 'Beautiful colours. Would have liked the bug to have been a little less soft.', '2019-06-19 16:45:34.000000', NULL, 1),
